head.script:
// 지표 발행기관 찾기

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.ins_search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91400.btn_close_onclick" });
    }
};

/**
 * @method
 * @name dts_List1_OnLoadError
 * @description dts_List1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91400.dts_List1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadError
 * @description dts_List2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91400.dts_List2_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid1_OnDblClick
 * @description grd_Grid1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid1_OnDblClick = async function(row, colid) {
    try {
        const CD_VAL = dts_List1.getCellData(dts_List1.getRowPosition(), "CD_VAL");
        const INDIC_ISUR_CD = dts_List2.getCellData(row, "INDIC_ISUR_CD");
        const INDIC_ISUR_NM = dts_List2.getCellData(row, "INDIC_ISUR_NM");
        $c.frame.path("../").ins_popupRtn_cdnm(CD_VAL + INDIC_ISUR_CD, INDIC_ISUR_NM);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS91400.grd_Grid1_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 지표, 발행기관 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    const sbmOptions = {
        id : "sbm_dts_List1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_List2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
